metadata.script:
"use-strict";
let d = document.getElementsByTagName("JETK-head-button");
//console.log(d);
let isConfirm = true;
let isAway = false;
let fun = (event) => {
 if (isAway) return;
 //console.log (event.target.scrollTop, contentSize.height);'
 let l = ((event.target.scrollTop / contentSize.height) > 0.9);
 if (isConfirm !== (l)) {
  isConfirm = (l);
  for (let gi = 0; gi < 4; gi++) {
   let g = d[gi];
   g.style.display = (isConfirm && gi != 0) ? "flex" : "none";
   if (g.id == "QUIZ") g.style.display = !(isConfirm && gi != 0) ? "flex" : "none";

  }
 }

}

addOnLeave(() => {
 //for (let ts of ["scroll"]) content.removeEventListener(ts, fun);
 //window.removeEventListener("resize", fun);
});

